const transactions = $input.all().map(item => item.json);

const webhook = $('Webhook').first().json.body;

const userName =$('Webhook').first().json.user_name;
const question =$('Webhook').first().json.question;
const month = $('Webhook').first().json.month;

let totalIncome = 0;
let totalExpenses = 0;

const categorySpending = {};

for (const transaction of transactions) {
  const amount = Number(transaction.amount) || 0;

  if (transaction.transaction_type === 'income') {
    totalIncome += amount;
  } else {
    totalExpenses += amount;

    const category = transaction.category || 'Other';

    categorySpending[category] =
      (categorySpending[category] || 0) + amount;
  }
}

return [
  {
    json: {
      user_name:$('Webhook').first().json.user_name,
      question,
      month,
      total_income: totalIncome,
      total_expenses: totalExpenses,
      savings: totalIncome - totalExpenses,
      category_spending: categorySpending,
      transactions
    }
  }
];

